import collections

def top_k_frequent(nums, k):
    cnt = collections.Counter(nums)
    buckets = [[] for _ in range(len(nums) + 1)]
    for v, c in cnt.items():
        buckets[c].append(v)
    out = []
    for c in range(len(nums), 0, -1):
        for v in buckets[c]:
            out.append(v)
            if len(out) == k:
                return out
    return out

