vector<int> topKFrequent(vector<int>& nums, int k) {
    unordered_map<int, int> c; for (int x : nums) c[x]++;
    vector<vector<int>> b(nums.size() + 1);
    for (auto& [v, f] : c) b[f].push_back(v);
    vector<int> out;
    for (int f = nums.size(); f > 0 && (int)out.size() < k; f--) for (int v : b[f]) { out.push_back(v); if ((int)out.size() == k) break; }
    return out;
}
